// Differential checks of LoopEntry-pbo.js against Lean, generated by leanscript --check
import * as M from "./LoopEntry-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("countUp(\"\", 0, 0, 0)", () => M.countUp("", 0, 0, 0), "0", false);
check("countUp(\"\", 1, 0, 2)", () => M.countUp("", 1, 0, 2), "2", false);
check("countUp(\"a\", 0, 2, 0)", () => M.countUp("a", 0, 2, 0), "0", false);
check("countUp(\"\", 5, 1, 1)", () => M.countUp("", 5, 1, 1), "6", false);
check("countUp(\"héllo, wörld\", 1, 1, 0)", () => M.countUp("héllo, wörld", 1, 1, 0), "1", false);
check("countUp(\"\", 2, 0, 13)", () => M.countUp("", 2, 0, 13), "13", false);
check("countUp(\"a\", 1, 2, 2)", () => M.countUp("a", 1, 2, 2), "4", false);
check("countUp(\"hello world\", 0, 13, 0)", () => M.countUp("hello world", 0, 13, 0), "0", false);
check("countUp(\"héllo, wörld\", 0, 0, 5)", () => M.countUp("héllo, wörld", 0, 0, 5), "5", false);
check("countUp(\"hello world\", 13, 0, 1)", () => M.countUp("hello world", 13, 0, 1), "1", false);
check("countUp(\"\", 13, 1, 5)", () => M.countUp("", 13, 1, 5), "18", false);
check("countUp(\"a\", 5, 5, 1)", () => M.countUp("a", 5, 5, 1), "26", false);
check("countUp(\"héllo, wörld\", 2, 1, 2)", () => M.countUp("héllo, wörld", 2, 1, 2), "4", false);
check("countUp(\"abcabc\", 1, 5, 0)", () => M.countUp("abcabc", 1, 5, 0), "5", false);
check("countUp(\"a\", 2, 2, 13)", () => M.countUp("a", 2, 2, 13), "17", false);
check("countUp(\"hello world\", 1, 13, 2)", () => M.countUp("hello world", 1, 13, 2), "15", false);
check("countUp(\"abcabc\", 0, 2, 5)", () => M.countUp("abcabc", 0, 2, 5), "5", false);
check("countUp(\"héllo, wörld\", 13, 2, 1)", () => M.countUp("héllo, wörld", 13, 2, 1), "27", false);
check("countUp(\"a\", 13, 5, 5)", () => M.countUp("a", 13, 5, 5), "70", false);
check("countUp(\"héllo, wörld\", 5, 1, 13)", () => M.countUp("héllo, wörld", 5, 1, 13), "18", false);
check("countUp(\"abcabc\", 2, 5, 2)", () => M.countUp("abcabc", 2, 5, 2), "12", false);
check("countUp(\"hello world\", 2, 13, 13)", () => M.countUp("hello world", 2, 13, 13), "39", false);
check("countUp(\"abcabc\", 13, 13, 1)", () => M.countUp("abcabc", 13, 13, 1), "170", false);
check("countUp(\"abcabc\", 5, 5, 13)", () => M.countUp("abcabc", 5, 5, 13), "38", false);

console.log(`LoopEntry-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
